TU TAREA (RTRSC1006S · solo estos archivos: src/ai/astraura/mesh/__tests__/federation-radar.test.ts, src/lib/network/__tests__/malla-neuronas.test.ts):
1. Lee el código ACTUAL de main que prueban esos archivos y las pruebas tal como están hoy.
2. Añade SOLO los casos de abajo que prueban un comportamiento que main todavía no cubre, adaptados a la API de hoy. Un caso ya cubierto con otro nombre no se duplica; uno que prueba un contrato que main cambió a propósito se descarta.
3. Si un caso destapa un fallo REAL, dilo en tu respuesta (el código no está en tus archivos).
4. Si ningún caso aporta, responde `NO APLICA: <motivo>` y para.
5. Ejecuta las pruebas de esos archivos y lee el resumen entero.
Pruebas TS: funciones puras o @testing-library; prohibido `vi.mock` de módulos de Node e importar un `route.ts`.

CASOS DE LA RAMA (material, no una orden de copiar):
```
# src/ai/astraura/mesh/__tests__/federation-radar.test.ts
  it("reduce Wi-Fi y Bluetooth a recuentos sin nombres", () => {
    const r = resumenCon([
      ["ip:1", "ip"], ["ip:2", "ip"], ["ip:3", "ip"],
      ["ble:1", "ble"], ["ble:2", "ble"],
      ["lora:1", "lora"],
    ]);
    const red = reducirResumenParaFederacion(r);
    expect(red.senales).toHaveLength(3);
    const wifi = red.senales.find((s) => s.id === "conteo:wifi");
    const ble = red.senales.find((s) => s.id === "conteo:ble");
    expect(wifi?.label).toBe("3 redes cercanas");
    expect(ble?.label).toBe("2 dispositivos Bluetooth");
    expect(red.senales.some((s) => s.id === "lora:1")).toBe(true);
    const texto = JSON.stringify(red);
    expect(texto).not.toContain("nombre-secreto-ip:1");
    expect(texto).not.toContain("nombre-secreto-ble:1");
    // La señal lora conserva su etiqueta (no es una red ajena).
    expect(texto).toContain("nombre-secreto-lora:1");
  });

# src/ai/astraura/mesh/__tests__/federation-radar.test.ts
  it("singular en los recuentos de uno", () => {
    const r = resumenCon([["ip:1", "ip"], ["ble:1", "ble"]]);
    const red = reducirResumenParaFederacion(r);
    expect(red.senales.find((s) => s.id === "conteo:wifi")?.label).toBe("1 red cercana");
    expect(red.senales.find((s) => s.id === "conteo:ble")?.label).toBe("1 dispositivo Bluetooth");
  });

# src/ai/astraura/mesh/__tests__/federation-radar.test.ts
  it("sin wifi ni ble no añade conteos", () => {
    const r = resumenCon([["lora:1", "lora"], ["serial:1", "serial"]]);
    const red = reducirResumenParaFederacion(r);
    expect(red.senales).toHaveLength(2);
    expect(red.senales.some((s) => s.id.startsWith("conteo:"))).toBe(false);
  });

# src/ai/astraura/mesh/__tests__/federation-radar.test.ts
  it("la primera publicación siempre sale", () => {
    expect(debePublicarResumenFederado("h1", null, 0, AHORA)).toBe(true);
  });

# src/ai/astraura/mesh/__tests__/federation-radar.test.ts
  it("nunca más de una vez cada 5 minutos, aunque cambie la huella", () => {
    expect(debePublicarResumenFederado("h2", "h1", AHORA - 60_000, AHORA)).toBe(false);
  });

# src/ai/astraura/mesh/__tests__/federation-radar.test.ts
  it("con huella nueva y 5 min pasados, publica", () => {
    expect(debePublicarResumenFederado("h2", "h1", AHORA - 6 * 60_000, AHORA)).toBe(true);
  });

# src/ai/astraura/mesh/__tests__/federation-radar.test.ts
  it("con la misma huella espera 15 minutos (latido)", () => {
    expect(debePublicarResumenFederado("h1", "h1", AHORA - 10 * 60_000, AHORA)).toBe(false);
    expect(debePublicarResumenFederado("h1", "h1", AHORA - 16 * 60_000, AHORA)).toBe(true);
  });

# src/lib/network/__tests__/malla-neuronas.test.ts
  test("solo cuenta lo oído hace menos de 60 s (nunca lo del futuro)", () => {
    const dets = [
      det("fresca", ahora - 10_000),
      det("al-limite", ahora - 59_999),
      det("caducada", ahora - 60_000),
      det("muy-vieja", ahora - 120_000),
      det("del-futuro", ahora + 5_000),
    ];
    expect(deteccionesBleRecientes(dets, ahora).map((d) => d.id)).toEqual(["fresca", "al-limite"]);
  });

# src/lib/network/__tests__/malla-neuronas.test.ts
  test("respeta una ventana distinta si se la dan", () => {
    const dets = [det("a", ahora - 30_000), det("b", ahora - 90_000)];
    expect(deteccionesBleRecientes(dets, ahora, 60_000).map((d) => d.id)).toEqual(["a"]);
    expect(deteccionesBleRecientes(dets, ahora, 120_000).map((d) => d.id)).toEqual(["a", "b"]);
  });

# src/lib/network/__tests__/malla-neuronas.test.ts
  test("sin envío previo, siempre envía (primera vez)", () => {
    expect(hayQueEnviarRadar(huella, null, 1_000)).toBe(true);
  });

# src/lib/network/__tests__/malla-neuronas.test.ts
  test("misma huella recién enviada, no vuelve a molestar el canal", () => {
    expect(hayQueEnviarRadar(huella, { huella, at: 1_000 }, 1_000 + RADAR_LOCAL_CADA_MS)).toBe(false);
  });

# src/lib/network/__tests__/malla-neuronas.test.ts
  test("huella distinta envía aunque el último fuera hace un segundo", () => {
    expect(hayQueEnviarRadar("h-nueva", { huella, at: 1_000 }, 1_001)).toBe(true);
  });

# src/lib/network/__tests__/malla-neuronas.test.ts
  test("misma huella se renueva a los 5 min exactos, ni un ms antes", () => {
    const ultimo = { huella, at: 1_000 };
    expect(hayQueEnviarRadar(huella, ultimo, 1_000 + RADAR_REENVIO_MS - 1)).toBe(false);
    expect(hayQueEnviarRadar(huella, ultimo, 1_000 + RADAR_REENVIO_MS)).toBe(true);
  });

# src/lib/network/__tests__/malla-neuronas.test.ts
  test("un reenvío personalizado también caduca a su tiempo", () => {
    expect(hayQueEnviarRadar(huella, { huella, at: 100 }, 100 + 10_000, 10_000)).toBe(true);
  });
